import {supabase} from './auth-client.mjs';
import {applyBox,applyBanner,bannerURL} from './guide-media.mjs';
export function installMedia({getActive,getPage,run,status}){
 const $=id=>document.getElementById(id);let data={banners:[],boxes:[]},available=false;
 async function rpc(action,payload={}){const {data,error}=await supabase.rpc('admin_guide_media',{p_action:action,p_payload:payload});if(error)throw Error(error.message);return data;}
 function banner(){return data.banners.find(b=>b.page_key===getPage())??{revision:0};}
 function box(){const active=getActive();return data.boxes.find(b=>b.page_key===active?.page_key&&b.block_key===active?.block_key)??{revision:0};}
 function paint(){const active=getActive();$('box-controls').hidden=!active?.block_key.startsWith('note-');const current=box();$('box-kind').value=current.kind??(active?.label.startsWith('Disclaimer')?'disclaimer':'info');for(const b of document.querySelectorAll('[data-media-action]'))b.disabled=!available;$('banner-meta').textContent=available?'Banner revision '+banner().revision:'Apply migration 012 to activate uploads and box controls.';const path=banner().draft_path??banner().published_path;$('banner-image').hidden=!path;if(path)$('banner-image').src=bannerURL(path);}
 async function refresh(){try{const next=await rpc('load');if(!next||!Array.isArray(next.banners)||!Array.isArray(next.boxes))throw Error('Media setup unavailable');data=next;available=true;}catch{available=false;}paint();const doc=$('content-preview').contentDocument;if(doc?.URL===new URL(getPage(),new URL('.',import.meta.url)).href)preview(doc);}
 function preview(doc){if(!doc)return;const page=getPage();applyBanner(doc,data.banners.find(b=>b.page_key===page)?.published_path);for(const b of data.boxes.filter(b=>b.page_key===page)){const target=doc.querySelector('[data-site-content="'+b.block_key+'"]');if(target)applyBox(target,b.kind);}}
 $('upload-banner').onclick=()=>run(async()=>{const file=$('banner-file').files[0];if(!file)throw Error('Choose a banner image.');const types={'image/png':'png','image/jpeg':'jpg','image/webp':'webp'};if(!types[file.type]||file.size>5242880)throw Error('Use PNG, JPG or WebP up to 5 MB.');const page=getPage(),revision=banner().revision,path=page.replace(/[^a-z0-9]/g,'-')+'/'+crypto.randomUUID()+'.'+types[file.type];const {error}=await supabase.storage.from('guide-banners').upload(path,file,{contentType:file.type,upsert:false});if(error)throw Error(error.message);await rpc('draft_banner',{page,path,revision});await refresh();status('Banner uploaded as a draft. Preview it before publishing.');});
 $('preview-banner').onclick=()=>{const path=banner().draft_path;if(!path){status('Upload a banner draft first.');return;}const doc=$('content-preview').contentDocument;if(doc)applyBanner(doc,path);};
 $('publish-banner').onclick=()=>run(async()=>{await rpc('publish_banner',{page:getPage(),revision:banner().revision});await refresh();$('content-preview').src=$('content-preview').src;status('Banner published.');});
 $('reset-banner').onclick=()=>run(async()=>{await rpc('reset_banner',{page:getPage(),revision:banner().revision});await refresh();$('content-preview').src=$('content-preview').src;status('Original page banner restored.');});
 $('publish-box').onclick=()=>run(async()=>{const active=getActive();await rpc('set_box',{page:active.page_key,block:active.block_key,revision:box().revision,kind:$('box-kind').value});await refresh();preview($('content-preview').contentDocument);status('Box style published. Text is managed separately in the editor.');});
 $('reset-box').onclick=()=>run(async()=>{const active=getActive();await rpc('reset_box',{page:active.page_key,block:active.block_key,revision:box().revision});await refresh();$('content-preview').src=$('content-preview').src;status('Original box style restored.');});
 $('export-published').onclick=()=>run(async()=>{const bundle=await rpc('export');bundle.banners=bundle.banners.filter(b=>b.published_path).map(({page_key,published_path,revision})=>({page_key,published_path,revision}));const {SUPABASE_URL}=await import('./supabase-config.mjs');bundle.storageBase=SUPABASE_URL;const blob=new Blob([JSON.stringify(bundle,null,2)],{type:'application/json'});const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='milkroad-published-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('Export downloaded. Use the local sync command shown below.');});
 return {refresh,paint,preview};
}
